import Foundation
import Testing
@testable import CoreScopeViewer

/// Saved-plans v3 contract gate: Swift must reproduce the shared vectors exactly. The same file is
/// checked by Android's PortableContractTest, and both are generated by an independent Python reference.
struct PortableContractTests {
    private let vectors: [String: Any]

    init() throws {
        var root = URL(fileURLWithPath: #filePath).resolvingSymlinksInPath().deletingLastPathComponent()
        let path = "shared/fixtures/saved-plans/contract-vectors-v1.json"
        while root.path != "/" && !FileManager.default.fileExists(atPath: root.appendingPathComponent(path).path) {
            root.deleteLastPathComponent()
        }
        vectors = try JSONSerialization.jsonObject(with: Data(contentsOf: root.appendingPathComponent(path))) as! [String: Any]
    }

    private func double(_ value: Any?) -> Double {
        Double(bitPattern: UInt64((value as! String).dropFirst(2), radix: 16)!)
    }
    private func bits(_ value: Double) -> String { "0x" + String(format: "%016llx", value.bitPattern) }
    private func cases(_ key: String) -> [[String: Any]] { vectors[key] as! [[String: Any]] }

    @Test func coverageFingerprintsMatchTheReference() throws {
        #expect(cases("coverageInputs").count == 9)
        for vector in cases("coverageInputs") {
            let input = vector["input"] as! [String: Any]
            let doubles = ["transmitterLatitude", "transmitterLongitude", "frequencyMHz", "transmitHeightMeters",
                           "receiveHeightMeters", "transmitPowerDbm", "transmitGainDbi", "receiveGainDbi", "transmitLossDb",
                           "receiveLossDb", "sensitivityDbm", "reserveDb"].map { double(input[$0]) }
            let grid = ["radiusMeters", "spacingMeters", "minEastMeters", "maxNorthMeters", "columns", "rows"]
                .map { Int64(input[$0] as! Int) }
            let nodes = (input["nodes"] as! [[String: Any]]).map {
                PortableInputFingerprint.Node(sourceID: $0["sourceID"] as! String, nodeID: $0["nodeID"] as! String,
                                              latitude: double($0["latitude"]), longitude: double($0["longitude"]))
            }
            let digest = try PortableInputFingerprint.coverage(doubles: doubles, grid: grid,
                catalogComplete: input["catalogComplete"] as! Bool, nodes: nodes)
            #expect(digest == vector["sha256"] as? String, "\(vector["name"]!)")
        }
    }

    @Test func coverageAdapterReadsEngineInputsInContractOrder() throws {
        let vector = cases("coverageInputs")[0]
        let input = vector["input"] as! [String: Any]
        let grid = try CoverageGrid(radiusMeters: 16093, spacingMeters: 1609, minEastMeters: -16090, maxEastMeters: 16090,
                                    minNorthMeters: -16090, maxNorthMeters: 16090)
        let inputs = try CoverageStudyInputs(
            transmitter: CoverageTerrainCoordinate(latitude: double(input["transmitterLatitude"]), longitude: double(input["transmitterLongitude"])),
            grid: grid,
            budget: CoverageLinkBudget(transmitPowerDbm: double(input["transmitPowerDbm"]), transmitGainDbi: double(input["transmitGainDbi"]),
                receiveGainDbi: double(input["receiveGainDbi"]), transmitLossDb: double(input["transmitLossDb"]),
                receiveLossDb: double(input["receiveLossDb"]), sensitivityDbm: double(input["sensitivityDbm"]),
                reserveDb: double(input["reserveDb"])),
            frequencyMHz: double(input["frequencyMHz"]), transmitHeightMeters: double(input["transmitHeightMeters"]),
            receiveHeightMeters: double(input["receiveHeightMeters"]))
        let nodes = (input["nodes"] as! [[String: Any]]).map {
            CoverageNodeSnapshot(sourceID: $0["sourceID"] as! String, nodeID: $0["nodeID"] as! String,
                                 latitude: double($0["latitude"]), longitude: double($0["longitude"]))
        }
        #expect(try PortableInputFingerprint.coverage(inputs, nodes: nodes, catalogComplete: false) == vector["sha256"] as? String)
    }

    @Test func linkProfileFingerprintsMatchTheReference() throws {
        #expect(cases("linkProfileInputs").count == 8)
        for vector in cases("linkProfileInputs") {
            let input = vector["input"] as! [String: Any]
            func endpoint(_ name: String) -> SavedEndpoint {
                let point = input[name] as! [String: Any]
                // Names are labels and must not change the fingerprint.
                return SavedEndpoint(name: "Any label", latitude: double(point["latitude"]), longitude: double(point["longitude"]),
                    antenna: SavedAntenna(heightMeters: double(point["heightMeters"]), gainDbi: double(point["gainDbi"]),
                                          lossDb: double(point["lossDb"])))
            }
            var profile = SavedLinkProfile(pointA: endpoint("pointA"), pointB: endpoint("pointB"),
                frequencyMHz: double(input["frequencyMHz"]), transmitPowerDbm: double(input["transmitPowerDbm"]),
                sensitivityDbm: double(input["sensitivityDbm"]), refractionK: double(input["refractionK"]),
                sampleCount: input["sampleCount"] as? Int)
            #expect(try PortableInputFingerprint.linkProfile(profile) == vector["sha256"] as? String, "\(vector["name"]!)")
            let labelled = try PortableInputFingerprint.linkProfile(profile)
            profile.pointA.name = nil
            #expect(try PortableInputFingerprint.linkProfile(profile) == labelled)
        }
    }

    /// The production budget recomputes each stored loss's margin bit for bit, so payloads can store losses only.
    @Test func productionBudgetRecomputesMarginsBitForBit() throws {
        for vector in cases("margins") {
            let b = vector["budget"] as! [String: Any]
            let budget = try CoverageLinkBudget(transmitPowerDbm: double(b["transmitPowerDbm"]), transmitGainDbi: double(b["transmitGainDbi"]),
                receiveGainDbi: double(b["receiveGainDbi"]), transmitLossDb: double(b["transmitLossDb"]),
                receiveLossDb: double(b["receiveLossDb"]), sensitivityDbm: double(b["sensitivityDbm"]), reserveDb: double(b["reserveDb"]))
            let reception = try budget.reception(pathLossDb: double(vector["lossDb"]))
            #expect(bits(budget.maximumLossDb) == vector["maximumLossDb"] as? String, "\(vector["name"]!)")
            #expect(bits(reception.adjustedMarginDb) == vector["adjustedMarginDb"] as? String, "\(vector["name"]!)")
            #expect(bits(reception.receiveLevelDbm) == vector["receiveLevelDbm"] as? String, "\(vector["name"]!)")
        }
    }

    /// Foundation parses the reference text exactly and its own encode/decode keeps every bit.
    @Test func jsonNumbersRoundTripBitExactly() throws {
        for vector in cases("jsonNumbers") {
            let expected = double(vector["bits"])
            let text = vector["text"] as! String
            let parsed = try JSONDecoder().decode([Double].self, from: Data("[\(text)]".utf8))[0]
            #expect(bits(parsed) == bits(expected), "parse \(text)")
            let encoded = try JSONEncoder().encode([expected])
            let decoded = try JSONDecoder().decode([Double].self, from: encoded)[0]
            #expect(bits(decoded) == bits(expected), "round trip \(String(decoding: encoded, as: UTF8.self))")
        }
    }

    @Test func nonFiniteInputsAreRefused() {
        var writer = PortableInputFingerprint.Writer(domain: "x")
        #expect(throws: PortableInputFingerprint.Failure.nonFinite) { try writer.double(.nan) }
        #expect(throws: PortableInputFingerprint.Failure.nonFinite) { try writer.double(.infinity) }
    }
}
